<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import AppSheet from '@/components/shared/AppSheet.vue'
import {cloneTracker,type CreativeTracker,type TrackerLog} from '@/types/trackers'
import {saveGridDay,trackerAssetUrl,uploadTrackerImage,trackerError} from '@/services/trackers.service'
const props=defineProps<{tracker:CreativeTracker;date:string;logs:TrackerLog[]}>()
const emit=defineEmits<{close:[];saved:[TrackerLog[]]}>()
const snapshot=cloneTracker(props.logs.filter(l=>l.tracker_id===props.tracker.id&&l.log_date===props.date))
const drafts=new Map<string,{note:string;photo:string}>()
const entries=computed(()=>props.logs.filter(l=>l.tracker_id===props.tracker.id&&l.log_date===props.date)),selected=ref(''),note=ref(''),photo=ref(''),url=ref(''),busy=ref(false),uploading=ref(false),error=ref('')
const entry=computed(()=>entries.value.find(l=>l.id===selected.value)||entries.value[0])
let generation=0
watch(entry,async(log,previous)=>{if(previous)drafts.set(previous.id,{note:note.value,photo:photo.value});const current=++generation,draft=log&&drafts.get(log.id);note.value=draft?.note??log?.values.note??'';photo.value=draft?.photo??log?.values.photo??'';url.value='';if(photo.value)try{const signed=await trackerAssetUrl(photo.value);if(current===generation)url.value=signed}catch{}},{immediate:true})
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=true;error.value='';try{photo.value=await uploadTrackerImage(file);url.value=await trackerAssetUrl(photo.value)}catch(e){error.value=trackerError(e)}finally{uploading.value=false}}
async function save(){if(!entry.value||busy.value||uploading.value)return;busy.value=true;error.value='';drafts.set(entry.value.id,{note:note.value,photo:photo.value});try{const entries=snapshot.map(log=>{const draft=drafts.get(log.id);return {id:log.id,values:draft?{...cloneTracker(log.values),note:draft.note,photo:draft.photo||undefined}:cloneTracker(log.values),timezone:log.timezone,started_at:log.started_at,ended_at:log.ended_at}});emit('saved',await saveGridDay(props.tracker.id,props.date,snapshot,entries))}catch(e){error.value=trackerError(e)}finally{busy.value=false}}
function close(){if(!busy.value&&!uploading.value)emit('close')}
</script>
<template><AppSheet :model-value="true" :title="tracker.name+' · Notes & photo'" @update:model-value="close"><div class="day-notes"><p class="day-context">{{new Date(date+'T12:00:00').toLocaleDateString('en-PH',{month:'long',day:'numeric',year:'numeric'})}}</p><div v-if="entries.length>1" class="note-sessions" aria-label="Notes for each sleep block"><button v-for="(log,i) in entries" :key="log.id" :disabled="busy||uploading" :aria-pressed="entry?.id===log.id" @click="selected=log.id">Block {{i+1}}{{log.values.note||log.values.photo?' · ✧':''}}</button></div><form id="grid-notes-form" @submit.prevent="save"><label>A little note<textarea v-model="note" rows="5" maxlength="5000" placeholder="Anything you’d like to remember…" :disabled="busy"/></label><label class="photo-button">＋ Add a private photo<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" :disabled="busy||uploading" @change="upload"/></label><div v-if="url" class="note-photo"><img :src="url" alt="Your photo for this day"/><button type="button" :disabled="busy||uploading" @click="photo='';url=''">Remove photo</button></div><p v-if="uploading" role="status">Keeping your photo…</p><p v-if="!entry" class="note-help">Choose and save your boxes first, then add a note or photo.</p><p v-if="error" role="alert">{{error}}</p></form></div><template #footer><div class="notes-actions"><button :disabled="busy||uploading" @click="close">Cancel</button><button form="grid-notes-form" type="submit" :disabled="busy||uploading||!entry">{{busy?'Saving…':'Save note & photo'}}</button></div></template></AppSheet></template>
<style scoped>.day-notes{color:#51493f}.day-context{margin:0 0 20px;color:#827568;font:italic 19px Georgia,serif}.day-notes form,.day-notes label{display:grid;gap:10px}.day-notes form{gap:18px}.day-notes label{font-size:14px}.day-notes textarea{width:100%;min-height:140px;padding:13px;border:1px solid #d7c9af;border-radius:5px;background:#fffdf6;color:#544c40;font-size:16px}.photo-button{position:relative;min-height:48px;display:flex!important;align-items:center;justify-content:center;border:1px dashed #baac8e;border-radius:5px;overflow:hidden}.photo-button input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}.note-photo img{max-width:100%;max-height:220px;border:5px solid #fff9ec}.note-photo button{display:block}.notes-actions,.note-sessions{display:flex;gap:8px;flex-wrap:wrap}.notes-actions{justify-content:space-between}.note-sessions{margin-bottom:15px}.day-notes button,.notes-actions button{min-height:44px;padding:10px 15px;border:1px solid #d2c2a5;border-radius:4px;background:#f4edde;color:#79283e;font-size:13px}.notes-actions button[type=submit]{background:#79283e;color:#fff9eb}.note-sessions button[aria-pressed=true]{border-color:#79283e;background:#eee2d1}.note-help{font-size:13px;line-height:1.6;color:#827568}[role=alert]{padding:12px;background:#f6e4dd;color:#91394e;font-size:13px}button:disabled{opacity:.5}button:focus-visible,textarea:focus-visible,.photo-button:focus-within{outline:2px solid #79283e;outline-offset:3px}</style>
